    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_events'::regclass AND conname='calculus_void_events_pkey') IS DISTINCT FROM 'PRIMARY KEY (reset_id)' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_events_pkey'; END IF;
    IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='target_private.calculus_void_ranges'::regclass AND relrowsecurity) THEN RAISE EXCEPTION 'Void RLS missing'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_ranges'::regclass AND conname='calculus_void_ranges_check') IS DISTINCT FROM 'CHECK ((((source_to >= 1) AND (source_to <= 1000000000)) AND (source_to > source_from)))' AND
      (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_ranges'::regclass AND conname='calculus_void_ranges_check') IS DISTINCT FROM 'CHECK (((source_to >= 1) AND (source_to <= 1000000000) AND (source_to > source_from)))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_ranges_check'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_ranges'::regclass AND conname='calculus_void_ranges_source_from_check') IS DISTINCT FROM 'CHECK (((source_from >= 0) AND (source_from <= 999999999)))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_ranges_source_from_check'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_ranges'::regclass AND conname='calculus_void_ranges_user_id_check') IS DISTINCT FROM 'CHECK ((user_id > 0))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_ranges_user_id_check'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_ranges'::regclass AND conname='calculus_void_ranges_reset_id_fkey') IS DISTINCT FROM 'FOREIGN KEY (reset_id) REFERENCES target_private.calculus_void_events(reset_id)' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_ranges_reset_id_fkey'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_ranges'::regclass AND conname='calculus_void_ranges_pkey') IS DISTINCT FROM 'PRIMARY KEY (reset_id, user_id, source_from, source_to)' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_ranges_pkey'; END IF;
    IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='target_private.calculus_void_receipts'::regclass AND relrowsecurity) THEN RAISE EXCEPTION 'Void RLS missing'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_check') IS DISTINCT FROM 'CHECK (((amount < 0) AND (amount = ((- (applied_through - previous_applied_through)) * 10000))))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_check'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_check1') IS DISTINCT FROM 'CHECK ((((balance_removed >= 0) AND (balance_removed <= (- amount))) AND ((balance_removed % (10)::bigint) = 0)))' AND
      (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_check1') IS DISTINCT FROM 'CHECK (((balance_removed >= 0) AND (balance_removed <= (- amount)) AND ((balance_removed % (10)::bigint) = 0)))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_check1'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_check2') IS DISTINCT FROM 'CHECK (((forgiven_amount = ((- amount) - balance_removed)) AND ((forgiven_amount % (10)::bigint) = 0)))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_check2'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_check3') IS DISTINCT FROM 'CHECK ((wallet_revision_after = (wallet_revision_before + 1)))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_check3'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_check4') IS DISTINCT FROM 'CHECK (((source_from <= previous_applied_through) AND (previous_applied_through < applied_through) AND (applied_through <= source_to) AND (applied_through <= imported_source_points)))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_check4'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_created_at_check') IS DISTINCT FROM 'CHECK (isfinite(created_at))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_created_at_check'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_imported_source_points_check') IS DISTINCT FROM 'CHECK (((imported_source_points >= 0) AND (imported_source_points <= 1000000000)))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_imported_source_points_check'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_wallet_revision_before_check') IS DISTINCT FROM 'CHECK (((wallet_revision_before >= 0) AND (wallet_revision_before <= ''9999999999999''::bigint)))' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_wallet_revision_before_check'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_member_id_fkey') IS DISTINCT FROM 'FOREIGN KEY (member_id) REFERENCES target_private.profiles(member_id)' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_member_id_fkey'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_reset_id_user_id_source_from_source_fkey') IS DISTINCT FROM 'FOREIGN KEY (reset_id, user_id, source_from, source_to) REFERENCES target_private.calculus_void_ranges(reset_id, user_id, source_from, source_to)' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_reset_id_user_id_source_from_source_fkey'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.calculus_void_receipts'::regclass AND conname='calculus_void_receipts_pkey') IS DISTINCT FROM 'PRIMARY KEY (reset_id, user_id, source_from, source_to, applied_through)' THEN RAISE EXCEPTION 'Hosted void constraint differs: calculus_void_receipts_pkey'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.profiles'::regclass AND conname='target_games_income_bounds') IS DISTINCT FROM 'CHECK ((((total_points >= 0) AND (total_points <= ''10000000000000''::bigint)) AND ((total_points % (10)::bigint) = 0) AND ((calculus_points >= 0) AND (calculus_points <= ''10000000000000''::bigint)) AND ((calculus_points % (10000)::bigint) = 0) AND ((birthday_points >= 0) AND (birthday_points <= ''20000000000000''::bigint)) AND ((birthday_points % (100000)::bigint) = 0) AND ((casino_net >= ''-10000000000000''::bigint) AND (casino_net <= ''10000000000000''::bigint)) AND ((casino_net % (10)::bigint) = 0) AND ((((((total_points - calculus_points) - birthday_points) - casino_net) - calculus_forgiven_points) >= 0) AND (((((total_points - calculus_points) - birthday_points) - casino_net) - calculus_forgiven_points) <= (correct_count * 100000))) AND ((((((total_points - calculus_points) - birthday_points) - casino_net) - calculus_forgiven_points) % (100)::bigint) = 0)))' AND
      (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.profiles'::regclass AND conname='target_games_income_bounds') IS DISTINCT FROM 'CHECK (((total_points >= 0) AND (total_points <= ''10000000000000''::bigint) AND ((total_points % (10)::bigint) = 0) AND ((calculus_points >= 0) AND (calculus_points <= ''10000000000000''::bigint)) AND ((calculus_points % (10000)::bigint) = 0) AND ((birthday_points >= 0) AND (birthday_points <= ''20000000000000''::bigint)) AND ((birthday_points % (100000)::bigint) = 0) AND ((casino_net >= ''-10000000000000''::bigint) AND (casino_net <= ''10000000000000''::bigint)) AND ((casino_net % (10)::bigint) = 0) AND ((((((total_points - calculus_points) - birthday_points) - casino_net) - calculus_forgiven_points) >= 0) AND (((((total_points - calculus_points) - birthday_points) - casino_net) - calculus_forgiven_points) <= (correct_count * 100000))) AND ((((((total_points - calculus_points) - birthday_points) - casino_net) - calculus_forgiven_points) % (100)::bigint) = 0)))' THEN RAISE EXCEPTION 'Hosted profile constraint differs: target_games_income_bounds'; END IF;
    IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.profiles'::regclass AND conname='profiles_calculus_forgiven_points_check') IS DISTINCT FROM 'CHECK ((((calculus_forgiven_points >= 0) AND (calculus_forgiven_points <= ''10000000000000''::bigint)) AND ((calculus_forgiven_points % (10)::bigint) = 0)))' AND
      (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='target_private.profiles'::regclass AND conname='profiles_calculus_forgiven_points_check') IS DISTINCT FROM 'CHECK (((calculus_forgiven_points >= 0) AND (calculus_forgiven_points <= ''10000000000000''::bigint) AND ((calculus_forgiven_points % (10)::bigint) = 0)))' THEN RAISE EXCEPTION 'Hosted profile constraint differs: profiles_calculus_forgiven_points_check'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_void_ranges'::regclass AND tgname='calculus_void_apply_existing' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_apply_existing AFTER INSERT ON target_private.calculus_void_ranges FOR EACH ROW EXECUTE FUNCTION target_private.apply_calculus_void_range()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_apply_existing'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_links'::regclass AND tgname='calculus_void_apply_import' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_apply_import AFTER INSERT OR UPDATE OF imported_source_points ON target_private.calculus_links FOR EACH ROW EXECUTE FUNCTION target_private.apply_calculus_void_import()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_apply_import'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_void_events'::regclass AND tgname='calculus_void_event_permanent' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_event_permanent BEFORE DELETE OR UPDATE ON target_private.calculus_void_events FOR EACH ROW EXECUTE FUNCTION target_private.protect_calculus_void_history()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_event_permanent'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_void_events'::regclass AND tgname='calculus_void_event_storage' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_event_storage AFTER INSERT ON target_private.calculus_void_events FOR EACH ROW EXECUTE FUNCTION target_private.calculus_void_storage()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_event_storage'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_void_ranges'::regclass AND tgname='calculus_void_range_permanent' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_range_permanent BEFORE DELETE OR UPDATE ON target_private.calculus_void_ranges FOR EACH ROW EXECUTE FUNCTION target_private.protect_calculus_void_history()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_range_permanent'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_void_ranges'::regclass AND tgname='calculus_void_range_storage' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_range_storage AFTER INSERT ON target_private.calculus_void_ranges FOR EACH ROW EXECUTE FUNCTION target_private.calculus_void_storage()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_range_storage'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_void_ranges'::regclass AND tgname='calculus_void_range_valid' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_range_valid BEFORE INSERT ON target_private.calculus_void_ranges FOR EACH ROW EXECUTE FUNCTION target_private.validate_calculus_void_range()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_range_valid'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_void_receipts'::regclass AND tgname='calculus_void_receipt_permanent' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_receipt_permanent BEFORE DELETE OR UPDATE ON target_private.calculus_void_receipts FOR EACH ROW EXECUTE FUNCTION target_private.protect_calculus_void_history()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_receipt_permanent'; END IF;
    IF (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='target_private.calculus_void_receipts'::regclass AND tgname='calculus_void_receipt_storage' AND NOT tgisinternal) IS DISTINCT FROM 'CREATE TRIGGER calculus_void_receipt_storage AFTER INSERT ON target_private.calculus_void_receipts FOR EACH ROW EXECUTE FUNCTION target_private.calculus_void_storage()' THEN RAISE EXCEPTION 'Hosted void trigger differs: calculus_void_receipt_storage'; END IF;
  END IF;
END;
$calculus_void_prerequisite$;


-- Mechanism only: no member IDs, dates, source totals or operation IDs are embedded.
CREATE TABLE target_private.wallet_restoration_events (
  reset_id text PRIMARY KEY CHECK(reset_id ~ '^[a-zA-Z0-9_-]{1,80}$'),
  cutoff_at timestamptz NOT NULL CHECK(isfinite(cutoff_at)),
  prepared_at timestamptz NOT NULL CHECK(isfinite(prepared_at)),
  source_manifest_sha256 text NOT NULL CHECK(source_manifest_sha256 ~ '^[a-f0-9]{64}$'),
  before_snapshot_sha256 text NOT NULL CHECK(before_snapshot_sha256 ~ '^[a-f0-9]{64}$'),
  member_count integer NOT NULL CHECK(member_count BETWEEN 0 AND 500),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(created_at)),
  CHECK(cutoff_at<=prepared_at AND prepared_at<=created_at)
);
CREATE TABLE target_private.wallet_restorations (
  reset_id text NOT NULL REFERENCES target_private.wallet_restoration_events(reset_id),
  member_id uuid NOT NULL REFERENCES target_private.profiles(member_id),
  before_state jsonb NOT NULL CHECK(jsonb_typeof(before_state)='object'),
  after_void_state jsonb NOT NULL CHECK(jsonb_typeof(after_void_state)='object'),
  restored_state jsonb NOT NULL CHECK(jsonb_typeof(restored_state)='object'),
  component_deltas jsonb NOT NULL CHECK(jsonb_typeof(component_deltas)='object'),
  spent_refund bigint NOT NULL CHECK(spent_refund BETWEEN 0 AND 10000000000000 AND spent_refund%100=0),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(created_at)),
  PRIMARY KEY(reset_id,member_id),
  CHECK((before_state->>'spentPoints')::bigint-(restored_state->>'spentPoints')::bigint=spent_refund),
  CHECK((restored_state->>'walletRevision')::bigint=(after_void_state->>'walletRevision')::bigint+1)
);
CREATE INDEX wallet_restorations_member ON target_private.wallet_restorations(member_id);
ALTER TABLE target_private.wallet_restoration_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE target_private.wallet_restorations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE target_private.wallet_restoration_events,target_private.wallet_restorations FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION target_private.protect_wallet_restoration()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
  RAISE EXCEPTION 'Financial restoration records are permanent' USING ERRCODE='42501';
END $$;
CREATE TRIGGER wallet_restoration_event_permanent BEFORE UPDATE OR DELETE ON target_private.wallet_restoration_events
  FOR EACH ROW EXECUTE FUNCTION target_private.protect_wallet_restoration();
CREATE TRIGGER wallet_restoration_permanent BEFORE UPDATE OR DELETE ON target_private.wallet_restorations
  FOR EACH ROW EXECUTE FUNCTION target_private.protect_wallet_restoration();

CREATE FUNCTION target_private.wallet_finance_state(p target_private.profiles)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
  SELECT jsonb_build_object('totalPoints',p.total_points,'spentPoints',p.spent_points,
    'calculusPoints',p.calculus_points,'birthdayPoints',p.birthday_points,'casinoNet',p.casino_net,
    'calculusForgivenPoints',p.calculus_forgiven_points,'walletRevision',p.wallet_revision,
    'rawStudyPoints',p.total_points-p.calculus_points-p.birthday_points-p.casino_net-p.calculus_forgiven_points,
    'bonusId',p.bonus_id,'bonusStartedAt',p.bonus_started_at,'bonusEndsAt',p.bonus_ends_at);
$$;
CREATE FUNCTION target_private.wallet_finance_snapshot()
RETURNS jsonb LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$
  SELECT jsonb_build_object('capturedAt',clock_timestamp(),'profiles',
    coalesce(jsonb_object_agg(p.member_id::text,target_private.wallet_finance_state(p)),'{}'::jsonb))
  FROM target_private.profiles p;
$$;

-- Ledger projection includes permanent correction deltas, never batch-parent net.
-- NULL projects the current entire history; a timestamp selects strictly before it.
CREATE FUNCTION target_private.wallet_finance_projection(p_cutoff timestamptz DEFAULT NULL)
RETURNS TABLE(member_id uuid,total_points bigint,spent_points bigint,calculus_points bigint,
  birthday_points bigint,casino_net bigint,calculus_forgiven_points bigint,raw_study_points bigint,map_spent bigint)
LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH study AS(SELECT a.member_id,sum(a.award_points)::bigint amount FROM target_private.answers a
   WHERE p_cutoff IS NULL OR a.created_at<p_cutoff GROUP BY a.member_id),
 calculus AS(SELECT a.member_id,sum(a.amount)::bigint amount FROM target_private.calculus_credits a
   WHERE p_cutoff IS NULL OR a.created_at<p_cutoff GROUP BY a.member_id),
 voids AS(SELECT a.member_id,sum(a.amount)::bigint amount,sum(a.forgiven_amount)::bigint forgiven
   FROM target_private.calculus_void_receipts a WHERE p_cutoff IS NULL OR a.created_at<p_cutoff GROUP BY a.member_id),
 gifts AS(SELECT a.member_id,sum(a.amount)::bigint amount FROM target_private.birthday_receipts a
   WHERE p_cutoff IS NULL OR a.created_at<p_cutoff GROUP BY a.member_id),
 games AS(SELECT a.member_id,sum(a.net)::bigint amount FROM target_private.casino_rounds a
   WHERE p_cutoff IS NULL OR a.created_at<p_cutoff GROUP BY a.member_id),
 spending AS(SELECT a.member_id,sum(a.cost)::bigint amount,sum(a.cost) FILTER(WHERE a.map_cost)::bigint map_amount FROM(
     SELECT member_id,cost,created_at,false map_cost FROM target_private.sticker_draws
     UNION ALL SELECT member_id,cost,created_at,false FROM target_private.item_draws
     UNION ALL SELECT member_id,cost,created_at,true FROM target_private.map_purchases
     UNION ALL SELECT member_id,cost,created_at,true FROM target_private.territory_orders) a
   WHERE p_cutoff IS NULL OR a.created_at<p_cutoff GROUP BY a.member_id),
 corrections AS(SELECT a.member_id,sum((a.component_deltas->>'rawStudyPoints')::bigint)::bigint study,
     sum((a.component_deltas->>'calculusPoints')::bigint)::bigint calculus,
     sum((a.component_deltas->>'birthdayPoints')::bigint)::bigint birthday,
     sum((a.component_deltas->>'casinoNet')::bigint)::bigint casino,
     sum((a.component_deltas->>'calculusForgivenPoints')::bigint)::bigint forgiven,
     sum((a.component_deltas->>'spentPoints')::bigint)::bigint spent
   FROM target_private.wallet_restorations a JOIN target_private.wallet_restoration_events e USING(reset_id)
   WHERE p_cutoff IS NULL OR e.created_at<p_cutoff GROUP BY a.member_id),
 components AS(SELECT p.member_id,coalesce(s.amount,0)+coalesce(r.study,0) study,
     coalesce(c.amount,0)+coalesce(v.amount,0)+coalesce(r.calculus,0) calculus,
     coalesce(b.amount,0)+coalesce(r.birthday,0) birthday,coalesce(g.amount,0)+coalesce(r.casino,0) casino,
     coalesce(v.forgiven,0)+coalesce(r.forgiven,0) forgiven,
     coalesce(x.amount,0)+coalesce(r.spent,0) spent,coalesce(x.map_amount,0) map_spent
   FROM target_private.profiles p LEFT JOIN study s USING(member_id) LEFT JOIN calculus c USING(member_id)
     LEFT JOIN voids v USING(member_id) LEFT JOIN gifts b USING(member_id) LEFT JOIN games g USING(member_id)
     LEFT JOIN spending x USING(member_id) LEFT JOIN corrections r USING(member_id))
 SELECT member_id,study+calculus+birthday+casino+forgiven,spent,calculus,birthday,casino,forgiven,study,map_spent FROM components;
$$;

-- Operator-only finalizer. The caller captures B under the global+profiles locks,
-- inserts the new authoritative source void ranges, then calls this in SAME tx.
-- P is the resulting current wallet; the permanent financial delta is A-P, not A-B.
CREATE FUNCTION target_private.restore_wallet_finances(p_reset_id text,p_cutoff timestamptz,
  p_before jsonb,p_source_manifest_sha256 text)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE
  e target_private.wallet_restoration_events%rowtype; p target_private.profiles%rowtype;
  target record; current_ledger record; b jsonb; middle jsonb; restored jsonb; delta jsonb;
  prepared timestamptz; members integer; refund bigint; previous_refund bigint; gacha_cost bigint;
  void_amount bigint; void_forgiven bigint; void_removed bigint; void_count bigint; audit_bytes bigint;
BEGIN
  IF p_reset_id IS NULL OR p_reset_id!~'^[a-zA-Z0-9_-]{1,80}$' OR p_cutoff IS NULL OR NOT isfinite(p_cutoff)
    OR p_cutoff>clock_timestamp() OR p_source_manifest_sha256 IS NULL OR p_source_manifest_sha256!~'^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid financial restoration metadata' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(991101);
  PERFORM 1 FROM target_private.system_state WHERE singleton FOR UPDATE;
  LOCK TABLE target_private.profiles IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO e FROM target_private.wallet_restoration_events WHERE reset_id=p_reset_id;
  IF FOUND THEN
    IF e.cutoff_at<>p_cutoff OR e.source_manifest_sha256<>p_source_manifest_sha256 THEN
      RAISE EXCEPTION 'Restoration ID is already bound to different metadata' USING ERRCODE='22023'; END IF;
    RETURN jsonb_build_object('resetId',e.reset_id,'cutoffAt',e.cutoff_at,'members',e.member_count,'replayed',true);
  END IF;
  IF p_before IS NULL OR jsonb_typeof(p_before)<>'object' OR NOT(p_before?&ARRAY['capturedAt','profiles'])
    OR (SELECT count(*) FROM jsonb_object_keys(p_before))<>2 OR jsonb_typeof(p_before->'capturedAt') IS DISTINCT FROM 'string'
    OR jsonb_typeof(p_before->'profiles') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Missing locked pre-void financial snapshot' USING ERRCODE='22023'; END IF;
  prepared:=(p_before->>'capturedAt')::timestamptz;
  IF prepared IS NULL OR NOT isfinite(prepared) OR prepared<p_cutoff OR prepared>clock_timestamp() THEN
    RAISE EXCEPTION 'Invalid pre-void financial snapshot time' USING ERRCODE='22023'; END IF;
  SELECT count(*) INTO members FROM target_private.profiles;
  IF (SELECT count(*) FROM jsonb_object_keys(p_before->'profiles'))<>members OR EXISTS(
    SELECT 1 FROM target_private.profiles a WHERE NOT(p_before->'profiles'?a.member_id::text)) THEN
    RAISE EXCEPTION 'Pre-void snapshot does not cover the exact locked roster' USING ERRCODE='23514'; END IF;
  -- Fail closed on unknown adjustments, missing histories or incomplete receipts.
  IF EXISTS(SELECT 1 FROM target_private.wallet_finance_projection(NULL) l JOIN target_private.profiles a USING(member_id)
    WHERE (a.total_points,a.spent_points,a.calculus_points,a.birthday_points,a.casino_net,a.calculus_forgiven_points)
      IS DISTINCT FROM (l.total_points,l.spent_points,l.calculus_points,l.birthday_points,l.casino_net,l.calculus_forgiven_points)) THEN
    RAISE EXCEPTION 'Wallet histories and current financial components disagree' USING ERRCODE='23514'; END IF;
  -- Preflight every member before audit inserts or profile updates.
  FOR p IN SELECT * FROM target_private.profiles ORDER BY member_id LOOP
    b:=p_before->'profiles'->p.member_id::text; middle:=target_private.wallet_finance_state(p);
    IF jsonb_typeof(b)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(b))<>11 OR NOT(b?&ARRAY[
      'totalPoints','spentPoints','calculusPoints','birthdayPoints','casinoNet','calculusForgivenPoints',
      'walletRevision','rawStudyPoints','bonusId','bonusStartedAt','bonusEndsAt']) THEN
      RAISE EXCEPTION 'Malformed pre-void member snapshot' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM unnest(ARRAY['totalPoints','spentPoints','calculusPoints','birthdayPoints','casinoNet',
        'calculusForgivenPoints','walletRevision','rawStudyPoints']) k
      WHERE jsonb_typeof(b->k) IS DISTINCT FROM 'number' OR b->>k !~'^-?(0|[1-9][0-9]{0,13})$') OR
      (b->>'totalPoints')::bigint NOT BETWEEN 0 AND 10000000000000 OR
      (b->>'spentPoints')::bigint NOT BETWEEN 0 AND (b->>'totalPoints')::bigint OR
      (b->>'calculusPoints')::bigint NOT BETWEEN 0 AND 10000000000000 OR
      (b->>'birthdayPoints')::bigint NOT BETWEEN 0 AND 20000000000000 OR
      (b->>'casinoNet')::bigint NOT BETWEEN -10000000000000 AND 10000000000000 OR
      (b->>'calculusForgivenPoints')::bigint NOT BETWEEN 0 AND 10000000000000 OR
      (b->>'walletRevision')::bigint NOT BETWEEN 0 AND 9999999999999 OR
      (b->>'rawStudyPoints')::bigint NOT BETWEEN 0 AND p.correct_count*100000 OR
      (b->>'totalPoints')::bigint%10<>0 OR (b->>'spentPoints')::bigint%100<>0 OR
      (b->>'calculusPoints')::bigint%10000<>0 OR (b->>'birthdayPoints')::bigint%100000<>0 OR
      (b->>'casinoNet')::bigint%10<>0 OR (b->>'calculusForgivenPoints')::bigint%10<>0 OR
      (b->>'rawStudyPoints')::bigint%100<>0 OR
      (b->>'rawStudyPoints')::bigint<>(b->>'totalPoints')::bigint-(b->>'calculusPoints')::bigint-
        (b->>'birthdayPoints')::bigint-(b->>'casinoNet')::bigint-(b->>'calculusForgivenPoints')::bigint THEN
      RAISE EXCEPTION 'Invalid pre-void member financial values' USING ERRCODE='22023'; END IF;
    IF p.wallet_revision<(b->>'walletRevision')::bigint OR p.wallet_revision>=10000000000000 OR
      p.spent_points<>(b->>'spentPoints')::bigint OR p.birthday_points<>(b->>'birthdayPoints')::bigint OR
      p.casino_net<>(b->>'casinoNet')::bigint OR middle->'rawStudyPoints'<>b->'rawStudyPoints' OR
      p.bonus_id::text IS DISTINCT FROM b->>'bonusId' OR
      coalesce(to_jsonb(p.bonus_started_at),'null'::jsonb) IS DISTINCT FROM b->'bonusStartedAt' OR
      coalesce(to_jsonb(p.bonus_ends_at),'null'::jsonb) IS DISTINCT FROM b->'bonusEndsAt' THEN
      RAISE EXCEPTION 'A non-void financial writer changed the prepared wallet' USING ERRCODE='23514'; END IF;
    SELECT coalesce(sum(amount),0),coalesce(sum(forgiven_amount),0),coalesce(sum(balance_removed),0),count(*)
      INTO void_amount,void_forgiven,void_removed,void_count FROM target_private.calculus_void_receipts
      WHERE member_id=p.member_id AND wallet_revision_before>=(b->>'walletRevision')::bigint AND wallet_revision_after<=p.wallet_revision;
    IF p.wallet_revision-(b->>'walletRevision')::bigint<>void_count OR
      p.calculus_points-(b->>'calculusPoints')::bigint<>void_amount OR
      p.calculus_forgiven_points-(b->>'calculusForgivenPoints')::bigint<>void_forgiven OR
      p.total_points-(b->>'totalPoints')::bigint<> -void_removed THEN
      RAISE EXCEPTION 'Prepared wallet changes are not exactly covered by source void receipts' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT target FROM target_private.wallet_finance_projection(p_cutoff) l WHERE l.member_id=p.member_id;
    SELECT * INTO STRICT current_ledger FROM target_private.wallet_finance_projection(NULL) l WHERE l.member_id=p.member_id;
    refund:=p.spent_points-target.spent_points;
    SELECT coalesce(sum(spent_refund),0) INTO previous_refund FROM target_private.wallet_restorations WHERE member_id=p.member_id;
    SELECT coalesce(sum(cost),0) INTO gacha_cost FROM(SELECT cost FROM target_private.sticker_draws WHERE member_id=p.member_id
      UNION ALL SELECT cost FROM target_private.item_draws WHERE member_id=p.member_id) receipts;
    IF target.map_spent<>current_ledger.map_spent OR refund<0 OR refund%100<>0 OR previous_refund+refund>gacha_cost OR
      target.total_points NOT BETWEEN 0 AND 10000000000000 OR target.total_points%10<>0 OR
      target.spent_points NOT BETWEEN 0 AND target.total_points OR target.spent_points%100<>0 OR
      target.calculus_points NOT BETWEEN 0 AND 10000000000000 OR target.calculus_points%10000<>0 OR
      target.birthday_points NOT BETWEEN 0 AND 20000000000000 OR target.birthday_points%100000<>0 OR
      target.casino_net NOT BETWEEN -10000000000000 AND 10000000000000 OR target.casino_net%10<>0 OR
      target.calculus_forgiven_points NOT BETWEEN 0 AND 10000000000000 OR target.calculus_forgiven_points%10<>0 OR
      target.raw_study_points NOT BETWEEN 0 AND p.correct_count*100000 OR target.raw_study_points%100<>0 THEN
      RAISE EXCEPTION 'Historical restoration projection is invalid or includes unsupported map refunds' USING ERRCODE='23514'; END IF;
  END LOOP;
  audit_bytes:=1024+members*4096;
  UPDATE target_private.system_state SET logical_bytes=logical_bytes+audit_bytes
    WHERE singleton AND logical_bytes<=104857600-audit_bytes;
  IF NOT FOUND THEN RAISE EXCEPTION 'Financial restoration audit exceeds storage capacity' USING ERRCODE='54000'; END IF;
  INSERT INTO target_private.wallet_restoration_events(reset_id,cutoff_at,prepared_at,source_manifest_sha256,before_snapshot_sha256,member_count)
    VALUES(p_reset_id,p_cutoff,prepared,p_source_manifest_sha256,encode(sha256(convert_to(p_before::text,'UTF8')),'hex'),members);
  FOR p IN SELECT * FROM target_private.profiles ORDER BY member_id LOOP
    b:=p_before->'profiles'->p.member_id::text; middle:=target_private.wallet_finance_state(p);
    SELECT * INTO STRICT target FROM target_private.wallet_finance_projection(p_cutoff) l WHERE l.member_id=p.member_id;
    UPDATE target_private.profiles SET total_points=target.total_points,spent_points=target.spent_points,
      calculus_points=target.calculus_points,birthday_points=target.birthday_points,casino_net=target.casino_net,
      calculus_forgiven_points=target.calculus_forgiven_points,bonus_id=NULL,bonus_started_at=NULL,bonus_ends_at=NULL,updated_at=now()
      WHERE member_id=p.member_id RETURNING target_private.wallet_finance_state(profiles) INTO restored;
    delta:=jsonb_build_object('totalPoints',(restored->>'totalPoints')::bigint-(middle->>'totalPoints')::bigint,
      'spentPoints',(restored->>'spentPoints')::bigint-(middle->>'spentPoints')::bigint,
      'calculusPoints',(restored->>'calculusPoints')::bigint-(middle->>'calculusPoints')::bigint,
      'birthdayPoints',(restored->>'birthdayPoints')::bigint-(middle->>'birthdayPoints')::bigint,
      'casinoNet',(restored->>'casinoNet')::bigint-(middle->>'casinoNet')::bigint,
      'calculusForgivenPoints',(restored->>'calculusForgivenPoints')::bigint-(middle->>'calculusForgivenPoints')::bigint,
      'rawStudyPoints',(restored->>'rawStudyPoints')::bigint-(middle->>'rawStudyPoints')::bigint);
    INSERT INTO target_private.wallet_restorations(reset_id,member_id,before_state,after_void_state,restored_state,component_deltas,spent_refund)
      VALUES(p_reset_id,p.member_id,b,middle,restored,delta,(b->>'spentPoints')::bigint-(restored->>'spentPoints')::bigint);
  END LOOP;
  IF EXISTS(SELECT 1 FROM target_private.wallet_finance_projection(NULL) l JOIN target_private.profiles a USING(member_id)
    WHERE (a.total_points,a.spent_points,a.calculus_points,a.birthday_points,a.casino_net,a.calculus_forgiven_points)
      IS DISTINCT FROM (l.total_points,l.spent_points,l.calculus_points,l.birthday_points,l.casino_net,l.calculus_forgiven_points)) THEN
    RAISE EXCEPTION 'Restored wallets do not reconcile with permanent financial adjustments' USING ERRCODE='23514'; END IF;
  RETURN jsonb_build_object('resetId',p_reset_id,'cutoffAt',p_cutoff,'members',members,'replayed',false);
END $$;
REVOKE ALL ON FUNCTION target_private.protect_wallet_restoration(),target_private.wallet_finance_state(target_private.profiles),
  target_private.wallet_finance_snapshot(),target_private.wallet_finance_projection(timestamptz),
  target_private.restore_wallet_finances(text,timestamptz,jsonb,text) FROM PUBLIC,anon,authenticated,service_role;

-- Single operator call covers both source exclusion and financial restoration.
-- A completed operation is checked BEFORE any source event/range can be added.
CREATE FUNCTION target_private.apply_wallet_restoration(p_reset_id text,p_cutoff timestamptz,
  p_source_day date,p_source_cutoff timestamptz,p_source_manifest_sha256 text,p_ranges jsonb,p_source_baselines jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE e target_private.wallet_restoration_events%rowtype; source_event target_private.calculus_void_events%rowtype;
  before_snapshot jsonb; item jsonb;
BEGIN
  IF p_reset_id IS NULL OR p_reset_id!~'^[a-zA-Z0-9_-]{1,80}$' OR p_cutoff IS NULL OR NOT isfinite(p_cutoff)
    OR p_source_day IS NULL OR NOT isfinite(p_source_day) OR p_source_cutoff IS NULL OR NOT isfinite(p_source_cutoff)
    OR p_cutoff>p_source_cutoff OR p_source_cutoff>clock_timestamp() OR p_source_manifest_sha256 IS NULL
    OR p_source_manifest_sha256!~'^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid restoration operation metadata' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(991101);
  PERFORM 1 FROM target_private.system_state WHERE singleton FOR UPDATE;
  LOCK TABLE target_private.profiles IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO e FROM target_private.wallet_restoration_events WHERE reset_id=p_reset_id;
  IF FOUND THEN
    SELECT * INTO source_event FROM target_private.calculus_void_events WHERE reset_id=p_reset_id;
    IF e.cutoff_at<>p_cutoff OR e.source_manifest_sha256<>p_source_manifest_sha256 OR source_event.reset_id IS NULL OR
      source_event.source_day<>p_source_day OR source_event.source_cutoff<>p_source_cutoff OR source_event.manifest_sha256<>p_source_manifest_sha256 THEN
      RAISE EXCEPTION 'Completed restoration ID has different source or financial metadata' USING ERRCODE='22023'; END IF;
    RETURN jsonb_build_object('resetId',e.reset_id,'cutoffAt',e.cutoff_at,'members',e.member_count,'replayed',true);
  END IF;
  IF EXISTS(SELECT 1 FROM target_private.calculus_void_events WHERE reset_id=p_reset_id) THEN
    RAISE EXCEPTION 'Source-only operation already uses this restoration ID' USING ERRCODE='22023'; END IF;
  IF p_source_baselines IS NULL OR jsonb_typeof(p_source_baselines) IS DISTINCT FROM 'array' OR
    jsonb_array_length(p_source_baselines)>1000 THEN
    RAISE EXCEPTION 'Invalid authoritative lifetime source baseline' USING ERRCODE='22023'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_source_baselines) LOOP
    IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(item))<>3 OR
      NOT(item?&ARRAY['userId','totalPoints','deleted']) THEN
      RAISE EXCEPTION 'Malformed authoritative lifetime source baseline' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM unnest(ARRAY['userId','totalPoints']) k WHERE jsonb_typeof(item->k) IS DISTINCT FROM 'number'
      OR item->>k !~'^(0|[1-9][0-9]{0,9})$') OR jsonb_typeof(item->'deleted') IS DISTINCT FROM 'boolean' OR
      (item->>'userId')::bigint NOT BETWEEN 1 AND 2147483647 OR (item->>'totalPoints')::bigint NOT BETWEEN 0 AND 1000000000 THEN
      RAISE EXCEPTION 'Invalid authoritative lifetime source baseline values' USING ERRCODE='22023'; END IF;
  END LOOP;
  IF (SELECT count(DISTINCT (value->>'userId')::integer) FROM jsonb_array_elements(p_source_baselines))<>jsonb_array_length(p_source_baselines) OR
    EXISTS(SELECT 1 FROM target_private.calculus_links l LEFT JOIN jsonb_array_elements(p_source_baselines) b
      ON (b->>'userId')::integer=l.user_id WHERE b IS NULL OR l.imported_source_points>(b->>'totalPoints')::bigint) THEN
    RAISE EXCEPTION 'Source baseline is stale or misses a current linked source' USING ERRCODE='23514'; END IF;
  IF p_ranges IS NULL OR jsonb_typeof(p_ranges) IS DISTINCT FROM 'array' OR jsonb_array_length(p_ranges)>1000 THEN
    RAISE EXCEPTION 'Invalid authoritative source exclusion intervals' USING ERRCODE='22023'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_ranges) LOOP
    IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(item))<>3 OR
      NOT(item?&ARRAY['userId','sourceFrom','sourceTo']) THEN
      RAISE EXCEPTION 'Malformed authoritative source exclusion interval' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM unnest(ARRAY['userId','sourceFrom','sourceTo']) k WHERE jsonb_typeof(item->k) IS DISTINCT FROM 'number'
      OR item->>k !~'^(0|[1-9][0-9]{0,9})$') OR (item->>'userId')::bigint NOT BETWEEN 1 AND 2147483647 OR
      (item->>'sourceFrom')::bigint NOT BETWEEN 0 AND 999999999 OR
      (item->>'sourceTo')::bigint NOT BETWEEN 1 AND 1000000000 OR
      (item->>'sourceFrom')::bigint>=(item->>'sourceTo')::bigint THEN
      RAISE EXCEPTION 'Invalid authoritative source exclusion interval values' USING ERRCODE='22023'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_ranges) r LEFT JOIN jsonb_array_elements(p_source_baselines) b
    ON (b->>'userId')::integer=(r->>'userId')::integer WHERE b IS NULL OR (r->>'sourceTo')::bigint>(b->>'totalPoints')::bigint) THEN
    RAISE EXCEPTION 'Source exclusion interval exceeds its authoritative lifetime baseline' USING ERRCODE='23514'; END IF;
  -- Every captured source prefix must be excluded, including deleted/unlinked IDs.
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_source_baselines) b WHERE (b->>'totalPoints')::bigint>0 AND
    (SELECT range_agg(int8range(r.source_from,least(r.source_to,(b->>'totalPoints')::bigint),'[)')) FROM(
      SELECT user_id,source_from,source_to FROM target_private.calculus_void_ranges
      UNION ALL SELECT (x->>'userId')::integer,(x->>'sourceFrom')::bigint,(x->>'sourceTo')::bigint FROM jsonb_array_elements(p_ranges) x) r
      WHERE r.user_id=(b->>'userId')::integer AND r.source_from<(b->>'totalPoints')::bigint)
    IS DISTINCT FROM int8multirange(int8range(0,(b->>'totalPoints')::bigint,'[)'))) THEN
    RAISE EXCEPTION 'Source exclusion intervals do not cover the captured lifetime prefix' USING ERRCODE='23514'; END IF;
  before_snapshot:=target_private.wallet_finance_snapshot();
  INSERT INTO target_private.calculus_void_events(reset_id,source_day,source_cutoff,manifest_sha256)
    VALUES(p_reset_id,p_source_day,p_source_cutoff,p_source_manifest_sha256);
  FOR item IN SELECT value FROM jsonb_array_elements(p_ranges) ORDER BY (value->>'userId')::integer,(value->>'sourceFrom')::bigint LOOP
    INSERT INTO target_private.calculus_void_ranges(reset_id,user_id,source_from,source_to)
      VALUES(p_reset_id,(item->>'userId')::integer,(item->>'sourceFrom')::bigint,(item->>'sourceTo')::bigint);
  END LOOP;
  -- Existing pending intervals are drained too, even when the new complement is empty.
  FOR item IN SELECT jsonb_build_object('userId',user_id) FROM target_private.calculus_links ORDER BY user_id LOOP
    PERFORM target_private.apply_calculus_voids((item->>'userId')::integer);
  END LOOP;
  RETURN target_private.restore_wallet_finances(p_reset_id,p_cutoff,before_snapshot,p_source_manifest_sha256);
END $$;
REVOKE ALL ON FUNCTION target_private.apply_wallet_restoration(text,timestamptz,date,timestamptz,text,jsonb,jsonb)
  FROM PUBLIC,anon,authenticated,service_role;

-- Keep all permanent inventory and expose refunded lifetime spend explicitly.
CREATE OR REPLACE FUNCTION target_private.wallet_snapshot(p_member uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
  WITH receipts AS (
    SELECT 'sticker'::text AS item_type,sticker_id AS item_id,cost FROM target_private.sticker_draws WHERE member_id=p_member
    UNION ALL SELECT item_type,coalesce(sticker_id,frame_id),cost FROM target_private.item_draws WHERE member_id=p_member
  ), quantities AS (SELECT item_type,item_id,count(*)::integer AS quantity FROM receipts GROUP BY item_type,item_id),
  refunds AS(SELECT coalesce(sum(spent_refund),0)::bigint amount FROM target_private.wallet_restorations WHERE member_id=p_member)
  SELECT jsonb_build_object('balance',p.total_points-p.spent_points,'totalIncome',p.total_points,'spent',p.spent_points,'walletRevision',p.wallet_revision,
    'mapSpent',coalesce((SELECT sum(cost) FROM target_private.map_purchases WHERE member_id=p_member),0)+coalesce((SELECT sum(cost) FROM target_private.territory_orders WHERE member_id=p_member),0),
    'price',100000,'catalogVersion',3,'catalogSize',17,'frameCatalogSize',33,'duplicatesAllowed',true,
    'drawCount',(SELECT count(*)::integer FROM receipts),'legacyDiscountedDraws',(SELECT count(*)::integer FROM receipts WHERE cost=10000),
    'frameOdds',jsonb_build_object('common',62,'rare',25,'epic',10,'legendary',3),
    'ownedStickers',coalesce((SELECT jsonb_agg(c.id ORDER BY c.ordinal) FROM target_private.sticker_catalog c JOIN quantities q ON q.item_type='sticker' AND q.item_id=c.id),'[]'::jsonb),
    'stickerQuantities',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'quantity',q.quantity) ORDER BY c.ordinal) FROM target_private.sticker_catalog c JOIN quantities q ON q.item_type='sticker' AND q.item_id=c.id),'[]'::jsonb),
    'ownedFrames',coalesce((SELECT jsonb_agg(c.id ORDER BY c.ordinal) FROM target_private.frame_catalog c JOIN quantities q ON q.item_type='frame' AND q.item_id=c.id),'[]'::jsonb),
    'frameQuantities',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'quantity',q.quantity) ORDER BY c.ordinal) FROM target_private.frame_catalog c JOIN quantities q ON q.item_type='frame' AND q.item_id=c.id),'[]'::jsonb))
    ||CASE WHEN refunds.amount>0 THEN jsonb_build_object('refundedSpend',refunds.amount) ELSE '{}'::jsonb END
  FROM target_private.profiles p CROSS JOIN refunds WHERE p.member_id=p_member;
$$;
REVOKE ALL ON FUNCTION target_private.wallet_snapshot(uuid) FROM PUBLIC,anon,authenticated,service_role;

COMMIT;
